S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os;q=sys.argv[1];t=max(1,int(sys.argv[2]));k=sys.argv[3];s=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));cw=lambda z:[w for w in("".join(c.lower()if c.isalnum()else" "for c in z).split())if w];r=cw(q);w=r or["being"];qn=" ".join(r);kv=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));sr=sum((i+1)*(b+1)for i,b in enumerate(open(s,"rb").read()if os.path.exists(s)else b""))%10**18;G=sum((b+1)*257**i for i,b in enumerate(J([qn,t,k,"onto-mml2"]).encode()));b=min(t,12);N=(1<<(b+1))-1;M=997+G%97;F=lambda j:(G+sr*j+j*j+kv)%M;tz=sum(F(j)&1 for j in range(N));nz=N-tz;O=min((F(j),j)for j in range(N));fac="BPM KEY SCL SEC CHD NOTE DUR VEL VOX PHON FMT MIX".split();SCL="maj min dor lyd".split();KEY="C D E F G A B".split();mus={"BPM":60+G%100,"KEY":KEY[G%7],"SCL":SCL[G%4],"SEC":["intro","verse","chorus","outro"],"CHD":[1,4,5,6],"NOTE":[(O[1]+i)%12 for i in range(4)],"DUR":[1,1,2,1],"VEL":60+kv%40,"VOX":"chant","PHON":w[0][:6],"FMT":[500+G%400,1400+kv%500,2400+O[1]%600],"MIX":[80,20]};ttl="Onto MML2 %s V%s"%(w[0].title(),k);V=int(set(fac)==set(mus)and tz+nz==N and O==min((F(j),j)for j in range(N)));D={"P":"RMZ-ANSELM-ONTO-NOSHA","MML":"RMZ-MML/2","GRAM":" ".join(fac)+" TITLE CERT","MUS":mus,"FORALL":"factor in GRAM; pi<N=>TZ xor NZ","Q":q,"QN":qn,"K":k,"SELF":sr,"ORIGIN":sr,"D0":1,"BND":b,"ALL":N,"TZ":tz,"NZ":nz,"CONS":int(tz+nz==N),"COMP":int(N==(1<<(b+1))-1),"OPT":O,"TITLE":ttl,"Ont":"MusicFactors>Voice>TT>Con>Comp>Verify>Cert","TT":"z0;AllMusicTM;TZC;NZO;VoiceC;certC","TM":"qMUS>qVoice>qAllTM>qTT>qCon>qComp>qVerify>qPCC>qZE","VERIFY":"recalc MUS/ALL/TZ/NZ/OPT/TITLE","REJECT":"not V","LK":"D/RCon/RComp","V":V,"PCC":V,"ZE":V,"Bd":"bounded music TM language;not full music/NL/RH/halt"};open("ONR.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"MML":D["MML"],"TITLE":ttl,"FACTORS":len(fac),"VOICE":mus["VOX"],"PCC":V,"ZE":V,"cert":"ONR.clcert","bytes":"<2048"}))' "$Q" "$T" "$K" "$S"